-- Brand reference data has stable IDs; source evidence and paid decisions stay intact.
CREATE TABLE brands (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE,
 name text NOT NULL CHECK(length(btrim(name))>0), revision integer NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE brand_aliases (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), brand_id uuid NOT NULL REFERENCES brands(id),
 name text NOT NULL, normalized_name text NOT NULL CHECK(length(normalized_name)>0),
 retailer text CHECK(retailer IN ('kam','ramstore','stokomak','spar','zito','vero','zur','dim','reptil')), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX brand_alias_unique ON brand_aliases(normalized_name,coalesce(retailer,''));
CREATE INDEX brand_alias_brand ON brand_aliases(brand_id);
CREATE TABLE brand_edits (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, brand_id uuid NOT NULL REFERENCES brands(id),
 actor text NOT NULL, before_record jsonb, after_record jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
WITH seed AS (SELECT * FROM jsonb_to_recordset('[{"slug":"coca-cola","name":"Coca-Cola","aliases":[{"name":"coca cola","normalized":"coca cola"},{"name":"koka kola","normalized":"koka kola"},{"name":"cocacola","normalized":"cocacola"},{"name":"kokakola","normalized":"kokakola"}]},{"slug":"pepsi","name":"Pepsi","aliases":[{"name":"pepsi","normalized":"pepsi"}]},{"slug":"fanta","name":"Fanta","aliases":[{"name":"fanta","normalized":"fanta"}]},{"slug":"schweppes","name":"Schweppes","aliases":[{"name":"schweppes","normalized":"schweppes"},{"name":"shveps","normalized":"shveps"}]},{"slug":"sinalco","name":"Sinalco","aliases":[{"name":"sinalco","normalized":"sinalco"},{"name":"sinalko","normalized":"sinalko"}]},{"slug":"bimilk","name":"BiMilk","aliases":[{"name":"bimilk","normalized":"bimilk"}]},{"slug":"imlek","name":"Imlek","aliases":[{"name":"imlek","normalized":"imlek"}]},{"slug":"dukat","name":"Dukat","aliases":[{"name":"dukat","normalized":"dukat"}]},{"slug":"alpsko","name":"Alpsko","aliases":[{"name":"alpsko","normalized":"alpsko"}]},{"slug":"milka","name":"Milka","aliases":[{"name":"milka","normalized":"milka"}]},{"slug":"nestle","name":"Nestle","aliases":[{"name":"nestle","normalized":"nestle"}]},{"slug":"nescafe","name":"Nescafé","aliases":[{"name":"nescafe","normalized":"nescafe"},{"name":"neskafe","normalized":"neskafe"}]},{"slug":"jacobs","name":"Jacobs","aliases":[{"name":"jacobs","normalized":"jacobs"},{"name":"jakobs","normalized":"jakobs"}]},{"slug":"podravka","name":"Podravka","aliases":[{"name":"podravka","normalized":"podravka"}]},{"slug":"vitalia","name":"Vitalia","aliases":[{"name":"vitalia","normalized":"vitalia"},{"name":"vitalija","normalized":"vitalija"}]},{"slug":"vitaminka","name":"Vitaminka","aliases":[{"name":"vitaminka","normalized":"vitaminka"}]},{"slug":"skopsko","name":"Skopsko","aliases":[{"name":"skopsko","normalized":"skopsko"}]},{"slug":"zlaten-dab","name":"Zlaten Dab","aliases":[{"name":"zlaten dab","normalized":"zlaten dab"}]},{"slug":"heineken","name":"Heineken","aliases":[{"name":"heineken","normalized":"heineken"},{"name":"hajneken","normalized":"hajneken"}]},{"slug":"babylino","name":"Babylino","aliases":[{"name":"babylino","normalized":"babylino"},{"name":"bebilino","normalized":"bebilino"},{"name":"bebylino","normalized":"bebylino"}]},{"slug":"dorina","name":"Dorina","aliases":[{"name":"dorina","normalized":"dorina"}]},{"slug":"koral","name":"Koral","aliases":[{"name":"koral","normalized":"koral"}]},{"slug":"amalfi","name":"Amalfi","aliases":[{"name":"amalfi","normalized":"amalfi"}]},{"slug":"vileda","name":"Vileda","aliases":[{"name":"vileda","normalized":"vileda"}]},{"slug":"astera","name":"Astera","aliases":[{"name":"astera","normalized":"astera"}]},{"slug":"kras","name":"Kraš","aliases":[{"name":"kras","normalized":"kras"}]},{"slug":"str8","name":"STR8","aliases":[{"name":"str8","normalized":"str8"},{"name":"str 8","normalized":"str 8"}]},{"slug":"ideal-shipka","name":"Ideal Šipka","aliases":[{"name":"ideal shipka","normalized":"ideal shipka"}]},{"slug":"nutella","name":"Nutella","aliases":[{"name":"nutella","normalized":"nutella"},{"name":"nutela","normalized":"nutela"}]},{"slug":"plazma","name":"Plazma","aliases":[{"name":"plazma","normalized":"plazma"},{"name":"bambi plazma","normalized":"bambi plazma"},{"name":"plazma bambi","normalized":"plazma bambi"}]},{"slug":"nivea","name":"Nivea","aliases":[{"name":"nivea","normalized":"nivea"},{"name":"niveja","normalized":"niveja"}]},{"slug":"fairy","name":"Fairy","aliases":[{"name":"fairy","normalized":"fairy"},{"name":"feri","normalized":"feri"}]},{"slug":"malena","name":"Malena","aliases":[{"name":"malena","normalized":"malena"}]},{"slug":"vincini","name":"Vincini","aliases":[{"name":"vincini","normalized":"vincini"},{"name":"vinchini","normalized":"vinchini"}]},{"slug":"happy-day","name":"Happy Day","aliases":[{"name":"happy day","normalized":"happy day"},{"name":"hepi dej","normalized":"hepi dej"}]},{"slug":"bio-zen","name":"Bio Zen","aliases":[{"name":"bio zen","normalized":"bio zen"}]},{"slug":"garden","name":"Garden","aliases":[{"name":"garden","normalized":"garden"}]},{"slug":"hipp","name":"HiPP","aliases":[{"name":"hipp","normalized":"hipp"},{"name":"hip","normalized":"hip"}]},{"slug":"yumis","name":"Yumis","aliases":[{"name":"yumis","normalized":"yumis"},{"name":"jumis","normalized":"jumis"}]},{"slug":"pfanner","name":"Pfanner","aliases":[{"name":"pfanner","normalized":"pfanner"},{"name":"faner","normalized":"faner"}]},{"slug":"dr benner","name":"Dr Benner","aliases":[{"name":"DR BENNER","normalized":"dr benner"}]},{"slug":"kosili","name":"Kosili","aliases":[{"name":"KOSILI","normalized":"kosili"}]},{"slug":"stark","name":"Stark","aliases":[{"name":"STARK","normalized":"stark"},{"name":"ШТАРК","normalized":"shtark"}]},{"slug":"hit","name":"Hit","aliases":[{"name":"HIT","normalized":"hit"}]},{"slug":"vochna dolina","name":"Vochna Dolina","aliases":[{"name":"VOCHNA DOLINA","normalized":"vochna dolina"},{"name":"VOCNA DOLINA","normalized":"vocna dolina"}]},{"slug":"kan bebe","name":"Kan Bebe","aliases":[{"name":"KAN BEBE","normalized":"kan bebe"},{"name":"KANBEBE","normalized":"kanbebe"}]},{"slug":"viva","name":"Viva","aliases":[{"name":"VIVA","normalized":"viva"}]}]'::jsonb) AS x(slug text,name text,aliases jsonb)), inserted AS (INSERT INTO brands(slug,name) SELECT slug,name FROM seed RETURNING id,slug) INSERT INTO brand_aliases(brand_id,name,normalized_name) SELECT b.id,a->>'name',a->>'normalized' FROM inserted b JOIN seed s USING(slug) CROSS JOIN LATERAL jsonb_array_elements(s.aliases) a ON CONFLICT DO NOTHING;

ALTER TABLE store_products ADD COLUMN brand_id uuid REFERENCES brands(id);
CREATE INDEX store_products_brand_id ON store_products(brand_id) WHERE brand_id IS NOT NULL;
-- Preserve existing text facts, including exact quotes and manual evidence.
UPDATE store_products sp SET brand_id=b.id FROM brands b WHERE b.slug=sp.facts->'brand'->>'value';
CREATE FUNCTION set_product_brand_reference() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 SELECT id INTO NEW.brand_id FROM brands WHERE slug=NEW.facts->'brand'->>'value';
 RETURN NEW;
END $$;
CREATE TRIGGER product_brand_reference BEFORE INSERT OR UPDATE OF facts ON store_products
 FOR EACH ROW EXECUTE FUNCTION set_product_brand_reference();
